public partial class Viewer {
 async Task WaitLandfall(Func<bool> done,double seconds=30){ulong start=Time.GetTicksMsec();while(!done()){if(Time.GetTicksMsec()-start>seconds*1000)throw new TimeoutException("Landfall state did not settle");await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);}}
 async Task LandfallShot(string name){missionPointer=new(-100,-100);QueueRedraw();await WarFrames(5);await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);using var image=GetViewport().GetTexture().GetImage();image.SavePng(Path.Combine(output,name+".png"));if(contentPanel!=null&&contentSetup!=null)File.AppendAllText(Path.Combine(output,"content-layout.txt"),$"{name} view={GetViewportRect()} ui={ui} panel={contentPanel.GetGlobalRect()} min={contentPanel.GetCombinedMinimumSize()} bottom={contentBottom!.GetGlobalRect()} import={contentImport.GetGlobalRect()}\n");}
 async Task VerifyLandfall(){
  Check(IsolatedPlayerData!=null,"Isolated Landfall profile");await WaitLandfall(()=>menuColony!=null);var args=OS.GetCmdlineUserArgs();ui=float.Parse(args.FirstOrDefault(a=>a.StartsWith("--landfall-scale="))?[17..]??"1",System.Globalization.CultureInfo.InvariantCulture);maximumAspect=args.Contains("--landfall-16")?16:0;ApplyAspectLimit();SavePresentationPreferences();ArtworkPreference.SaveAspect(artworkPreferencePath,maximumAspect);
  await LandfallShot("main");await SessionClick("options");await WarFrames(4);ActivateMissionUi("controls");await WarFrames(4);Check(missionPanel=="controls","Nested controls opens");await Send(Key.Escape);await WarFrames(4);Check(missionPanel=="options"&&focusedUi=="controls","Nested Back restores invoking focus");await Send(Key.Escape);await WarFrames(4);Check(mainMenu&&missionPanel.Length==0,"Options returns main menu");await SessionClick("campaign");await LandfallShot("campaign");
  foreach(string choice in new[]{"base:human","base:taar","training:human","council:human","council:taar"}){
   if(choice.StartsWith("council")&&!councilAvailable)continue;ActivateMissionUi("journey:"+choice);await LandfallShot(choice.Replace(':','-')+"-missions");Check(missionPanel=="missions","Faction selection routes to real mission list");ActivateMissionUi("campaign-start:0");await WarFrames(10);await LandfallShot(choice.Replace(':','-')+"-brief");RevealBriefing();await LandfallShot(choice.Replace(':','-')+"-complete");StartFirstStrike();AdvanceInterference(20);OpenMissionPanel("menu");await LandfallShot(choice.Replace(':','-')+"-pause");long tick=nativeWorld.Tick;await WarFrames(8);Check(nativeWorld.Tick==tick,"Single-player menu retains pause");OpenMissionPanel("options");optionScroll=0;await LandfallShot(choice.Replace(':','-')+"-options");optionScroll=99;await LandfallShot(choice.Replace(':','-')+"-options-bottom");SaveMissionSlot(0);LoadMissionSlot(0);Check(nativeWorld.Tick==tick,"Save/load tick preserved");ReturnMainMenu();
  }
  await LandfallShot("main-continue");OpenMissionPanel("load");await LandfallShot("load");OpenMissionPanel("quit-confirm");await LandfallShot("quit");CloseRelayPanel();OpenWarSetup();await WarFrames(40);await LandfallShot("war");foreach(string sheet in new[]{"maps","options"}){warSheet=sheet;warLayoutSize=Vector2.Zero;LayoutWarSetup();await LandfallShot("war-"+sheet);}HideWarSetup();OpenMultiplayer();await LandfallShot("multiplayer");CloseNetwork();
  if(ui==1&&GetViewportRect().Size.X==1920)await VerifyMenuPause();ReturnMainMenu();await WaitLandfall(()=>menuColony!=null);
  if(args.Contains("--landfall-reduced"))reducedMotion=true;ReplayRestoration();await WaitLandfall(()=>restorationWake>=0);Check(restorationVerified,"Replay validates active content without import");await LandfallShot("replay-contact");await ToSignal(GetTree().CreateTimer(reducedMotion?2.2:7),SceneTreeTimer.SignalName.Timeout);await LandfallShot("replay-awake");await WaitLandfall(()=>ready&&contentSetup==null);Check(mainMenu,"Replay returns to menu");
  File.WriteAllText(Path.Combine(output,"landfall-check.json"),JsonSerializer.Serialize(new{status="pass",ui,maximumAspect,input="Godot-dispatched and direct diagnostic navigation; not Windows input",listening="not performed",sidebar="Original drawing paths retained",gameplay="pause and save tick checks, no ordinary mission acceptance"}));
 }
 async void LandfallImportCheck(){try{
  Check(IsolatedPlayerData!=null,"Isolated importer profile");await LandfallShot("01-locate");string? source=OS.GetCmdlineUserArgs().FirstOrDefault(a=>a.StartsWith("--import-source="))?[16..];if(source==null)throw new ArgumentException("--import-source is required");
  if(OS.GetCmdlineUserArgs().Contains("--landfall-recovery")){
   string? prior=contentStore!.ActiveRoot;contentSource.Text=Path.Combine(output,"missing-original.iso");RunContentTask(InspectContent);await importTask!;await WarFrames(3);Check(contentPlan==null&&!restorationVerified,"Failed inspection cannot awaken");await LandfallShot("recovery-invalid");
   contentSource.Text=source;RunContentTask(InspectContent);await importTask!;Check(contentPlan!=null,"Retry source inspection");
   RunContentTask(async()=>{await DarkColony.ContentImport.ContentImporter.ImportAsync(contentPlan!,false,importCancel!.Token,p=>{importEvents.Enqueue(p);if(p.Stage==DarkColony.ContentImport.ImportStage.Copying)importCancel.Cancel();});});await importTask!;await WarFrames(4);Check(contentStore.ActiveRoot==prior&&!restorationVerified,"Cancel preserves active generation and cannot awaken");await LandfallShot("recovery-cancelled");
  }
  contentSource.Text=source;contentConsent.ButtonPressed=true;RunContentTask(InspectContent);await importTask!;Check(contentPlan!=null,"Inspect returns a real plan");await WarFrames(12);await LandfallShot("02-review");Check(contentImport.GetGlobalRect().End.Y<=GetViewportRect().End.Y,"Import action is visible above fold");
  RunContentTask(ImportContent);bool contact=false,skip=OS.GetCmdlineUserArgs().Contains("--landfall-skip");while(importTask is {IsCompleted:false}){if(!contact&&restorationContact>=0){contact=true;await ToSignal(GetTree().CreateTimer(.9),SceneTreeTimer.SignalName.Timeout);await LandfallShot("03-verified-contact");if(skip)RestorationInput(new InputEventKey{Keycode=Key.Space,Pressed=true});}Check(restorationWake<0,"No awakening before import task verification finishes");await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);}
  Check(restorationVerified,"Importer and active content verified");await WaitLandfall(()=>restorationWake>=0);await LandfallShot("04-awakening");if(!skip){await ToSignal(GetTree().CreateTimer(reducedMotion?2.2:7),SceneTreeTimer.SignalName.Timeout);await LandfallShot("05-the-colony-lives");}await WaitLandfall(()=>ready&&contentSetup==null);await WaitLandfall(()=>menuColony!=null);await LandfallShot("06-main");
  File.WriteAllText(Path.Combine(output,"restoration-check.json"),JsonSerializer.Serialize(new{success=true,contact,skip,verified=restorationVerified,sourcePreservation="External source hash comparison required",input="automated real importer",audibleAcceptance="not performed"}));await FinishFirstStrike(0);
 }catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
 async Task VerifyLandfallReplay(){
  Check(IsolatedPlayerData!=null,"Replay profile isolation");await WaitLandfall(()=>menuColony!=null);bool reduced=OS.GetCmdlineUserArgs().Contains("--landfall-reduced");reducedMotion=reduced;ReplayRestoration();await WaitLandfall(()=>restorationWake>=0);var scene=restorationColony;await LandfallShot("contact");await ToSignal(GetTree().CreateTimer(reduced?2.2:7),SceneTreeTimer.SignalName.Timeout);await LandfallShot("awake");await WaitLandfall(()=>ready&&contentSetup==null);await WarFrames(8);Check(ReferenceEquals(scene,menuColony)&&menuColony is {ArtReady:true},"Verified colony retained across menu handoff");await LandfallShot("main");File.WriteAllText(Path.Combine(output,"replay-check.json"),JsonSerializer.Serialize(new{pass=true,reduced,retainedScene=true,contentWrites=false,listening="not performed"}));
 }
 async Task VerifyLandfallResults(){
  Check(IsolatedPlayerData!=null,"Results fixture isolation");string source=OS.GetCmdlineUserArgs().Single(a=>a.StartsWith("--landfall-fixtures="))[20..];
  foreach(var pair in new[]{("human15/h01/controlled-success.json","human-victory"),("earth-intervenes/mission/failure.json","taar-defeat"),("final-evacuation/mission-final/success.json","taar-final")}){
   var state=SaveCodec.Open(Path.Combine(source,pair.Item1))["payload"]!.AsObject();var data=PersistenceData(state["scenario"]!.GetValue<string>());InstallMission(data,OriginalMission.Restore(data,state),false);missionOutcomeShown=true;outcomeText=ReadMissionText(mission.Outcome!.TextPath);ReleaseMissionVideo();BeginRewards();
   await ToSignal(GetTree().CreateTimer(.4),SceneTreeTimer.SignalName.Timeout);await LandfallShot(pair.Item2);Check(focusedUi==ResultDefault,"Result default "+pair.Item2);
   var actions=missionHits.Where(h=>h.Id is "main-menu" or "restart" or "continue").ToArray();Check(actions[0].Id=="main-menu"&&actions[1].Id=="restart","Exit then Replay");if(resultContinueAvailable){Check(actions[^1].Id=="continue","Continue rightmost");await Send(Key.Left);Check(focusedUi=="restart","Explicit keyboard Replay focus");await Send(Key.Right);}
   await Send(Key.Enter);if(pair.Item2=="human-victory")Check(missionBriefing&&mission.CampaignIndex==1,"Result Continue routes Human2");if(pair.Item2=="taar-final")Check(mainMenu,"Final Taar returns menu");ReturnMainMenu();
  }
  StartWarMatch(WarConfiguration.Default("A2PLAY01",7));AdvanceInterference(20);OpenMissionPanel("menu");ActivateMissionUi("war-surrender");await LandfallShot("war-surrender-confirm");ActivateMissionUi("abandon-confirm");await WarFrames(8);await LandfallShot("war-results");ReturnMainMenu();
  File.WriteAllText(Path.Combine(output,"results-check.txt"),"Controlled restored outcome fixtures and surrender; input isolation/default/focus/routing verified. Not ordinary victory.\n");
 }
 async Task VerifyLandfallPerformance(){
  Check(IsolatedPlayerData!=null,"Performance isolation");await WaitLandfall(()=>menuColony!=null);DisplayServer.WindowSetVsyncMode(DisplayServer.VSyncMode.Enabled);Engine.MaxFps=60;var rows=new List<object>();
  foreach(string phase in new[]{"menu","paused-options"}){
   if(phase!="menu"){ActivateMissionUi("journey:base:taar");ActivateMissionUi("campaign-start:0");RevealBriefing();StartFirstStrike();AdvanceInterference(200);OpenMissionPanel("options");}
   await ToSignal(GetTree().CreateTimer(2),SceneTreeTimer.SignalName.Timeout);long allocated=GC.GetTotalAllocatedBytes();int g0=GC.CollectionCount(0),g1=GC.CollectionCount(1),g2=GC.CollectionCount(2);using var process=System.Diagnostics.Process.GetCurrentProcess();long memory=process.PrivateMemorySize64;var frames=new List<double>(2000);ulong start=Time.GetTicksUsec(),last=start;
   while(Time.GetTicksUsec()-start<30000000){await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);ulong now=Time.GetTicksUsec();frames.Add((now-last)/1000d);last=now;}
   frames.Sort();process.Refresh();double P(double p)=>frames[Math.Min(frames.Count-1,(int)(frames.Count*p))];rows.Add(new{phase,seconds=(last-start)/1e6,frames=frames.Count,median=P(.5),p95=P(.95),p99=P(.99),worst=frames[^1],above33=frames.Count(v=>v>33.3),above50=frames.Count(v=>v>50),allocated=GC.GetTotalAllocatedBytes()-allocated,gen0=GC.CollectionCount(0)-g0,gen1=GC.CollectionCount(1)-g1,gen2=GC.CollectionCount(2)-g2,startMemory=memory,endMemory=process.PrivateMemorySize64});
  }
  File.WriteAllText(Path.Combine(output,"landfall-performance.json"),JsonSerializer.Serialize(new{viewport=GetViewportRect().Size.ToString(),ui,cap=60,classification="Process-frame wall gaps; optimized source, no screenshots during sampling; not GPU present or gameplay benchmark",rows},new JsonSerializerOptions{WriteIndented=true}));ReturnMainMenu();
 }

